Analyze the time and space complexity of the following function that sums all pairs in a list, and explain briefly.

def sum_pairs(arr):
    total = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            total += arr[i] + arr[j]
    return total

output:
def sum_pairs(arr):
    total = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            total += arr[i] + arr[j]
    return total

# Time: O(n^2) — nested loops iterate over roughly n*(n-1)/2 pairs.
# Space: O(1) — only a few scalar variables are used beyond the input.

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

# Time: O(log n) — each comparison halves the search interval; after k steps the interval length is n/2^k, which reaches 1 when k = log2(n).
# Space: O(1) for the iterative version (O(log n) if implemented recursively).

