Analyze the worst-case time complexity of quicksort with a bad pivot choice (always the smallest element).

def quicksort_bad(arr):
    if len(arr) <= 1:
        return arr
    pivot = min(arr)
    less = [x for x in arr if x < pivot]
    equal = [x for x in arr if x == pivot]
    greater = [x for x in arr if x > pivot]
    return quicksort_bad(less) + equal + quicksort_bad(greater)

output:
def quicksort_bad(arr):
    if len(arr) <= 1:
        return arr
    pivot = min(arr)
    less = [x for x in arr if x < pivot]
    equal = [x for x in arr if x == pivot]
    greater = [x for x in arr if x > pivot]
    return quicksort_bad(less) + equal + quicksort_bad(greater)

# Time: O(n^2) worst case — each split leaves n-1 elements in one partition, giving T(n) = T(n-1) + O(n).
# Space: O(n^2) worst recursion depth with list-copying version; O(n) with in-place partitioning.

class DynamicArray:
    def __init__(self):
        self.capacity = 1
        self.size = 0
        self.data = [None] * self.capacity
    def append(self, value):
        if self.size == self.capacity:
            self.capacity *= 2
            new_data = [None] * self.capacity
            for i in range(self.size):
                new_data[i] = self.data[i]
            self.data = new_data
        self.data[self.size] = value
        self.size += 1

# Time: O(1) amortized per append — a single resize of size c costs O(c), but that cost is spread over the c appends that fill the new buffer.
# Space: O(n) for n stored elements (plus transient O(c) during resize).

