def fib_iter(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Time: O(n) for the iterative version (the naive recursive version is O(2^n) due to repeated subproblems).
# Space: O(1) for the iterative version; O(n) recursion stack for naive recursion; O(n) with memoization.

