Given a function that iterates over all contiguous subarrays, analyze its time and space complexity.

def all_subarrays(arr):
    result = []
    n = len(arr)
    for i in range(n):
        current = []
        for j in range(i, n):
            current.append(arr[j])
            result.append(list(current))
    return result

Explain the difference between time complexity and space complexity, and analyze a function that trades extra space for speed (e.g., caching factorial values).

def factorial_cached(n, cache={}):
    if n in cache:
        return cache[n]
    if n <= 1:
        return 1
    cache[n] = n * factorial_cached(n - 1, cache)
    return cache[n]

output:
def factorial_cached(n, cache={}):
    if n in cache:
        return cache[n]
    if n <= 1:
        return 1
    cache[n] = n * factorial_cached(n - 1, cache)
    return cache[n]

# Time: O(n) first call (each value computed once); O(1) for subsequent cached calls.
# Space: O(n) for the cache storing factorial values from 0..n (plus O(n) recursion stack on first call).
# This is a classic space-for-time tradeoff: memoization trades O(n) memory for O(1) repeat lookups.

def heap_sort(arr):
    n = len(arr)
    def heapify(size, root):
        largest = root
        left, right = 2*root+1, 2*root+2
        if left < size and arr[left] > arr[largest]:
            largest = left
        if right < size and arr[right] > arr[largest]:
            largest = right
        if largest != root:
            arr[root], arr[largest] = arr[largest], arr[root]
            heapify(size, largest)
    for i in range(n//2 - 1, -1, -1):
        heapify(n, i)
    for i in range(n - 1, 0, -1):
        arr[0], arr[i] = arr[i], arr[0]
        heapify(i, 0)
    return arr

# Time: O(n log n) — building the heap is O(n), and each of the n extractions costs O(log n).
# Space: O(1) auxiliary (in-place, ignoring recursion stack of O(log n)) vs. merge sort's O(n) auxiliary space.
# Heap sort wins on space; merge sort is typically faster in practice due to cache locality.

def search_unsorted(arr, target):
    for i, x in enumerate(arr):
        if x == target:
            return i
    return -1

def search_sorted(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

# Unsorted linear search: O(n) time, O(1) space.
# Sorted binary search: O(log n) time, O(1) space — but the array must be sorted first, which costs O(n log n).
# Binary search wins for repeated queries: after one O(n log n) sort, m queries cost O(m log n) total vs. O(mn) for linear scans. For a single query on unsorted data, linear search (O(n)) is cheaper than sorting first.

