class HashMap:
    def __init__(self, size=16):
        self.size = size
        self.buckets = [[] for _ in range(size)]
    def _idx(self, key):
        return hash(key) % self.size
    def put(self, key, value):
        b = self.buckets[self._idx(key)]
        for i, (k, v) in enumerate(b):
            if k == key:
                b[i] = (key, value)
                return
        b.append((key, value))
    def get(self, key):
        for k, v in self.buckets[self._idx(key)]:
            if k == key:
                return v
        raise KeyError(key)

# Average case: O(1) for both put and get — a good hash spreads keys evenly, so each bucket holds ~n/m entries.
# Worst case: O(n) — if every key hashes to the same bucket (adversarial keys or a poor hash function),
#   each operation degenerates to a linear scan of all n entries.
# Cause of degradation: (1) hash collisions piling into one bucket, (2) poor load factor (n >> m) without resizing.
# Mitigation: resize/rehash when load factor exceeds ~0.75, keeping m proportional to n so average chain length stays O(1).
